<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Registry,Documents};
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B');INSERT INTO actors(id,club_id,role) VALUES('staff','a','members'),('member','a','member'),('foreign','b','members')");
$n=0;function check($ok,$label){global $n;if(!$ok)throw new RuntimeException($label);++$n;echo "PASS $label\n";}function denied(callable $f,$label){try{$f();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$r=new Registry($db,'staff');$one=$r->saveContact(null,0,'person','=HYPERLINK("https://example.invalid","Test")','one@example.invalid',"Teststraße 7\n01234 Musterort",['phone'=>'001234567','birthday'=>'1960-01-02']);$two=$r->saveContact(null,0,'person','Unselected Test','two@example.invalid','Other address');$foreign=(new Registry($db,'foreign'))->saveContact(null,0,'person','Foreign Test','','');
$bytes=$r->exportContacts([$one],['name','phone','address'],'xlsx');$path=tempnam(sys_get_temp_dir(),'kh-xlsx-test-');file_put_contents($path,$bytes);$zip=new ZipArchive();check($zip->open($path)===true,'real Excel ZIP opens');$files=[];for($i=0;$i<$zip->numFiles;$i++)$files[$zip->getNameIndex($i)]=$zip->getFromIndex($i);$zip->close();unlink($path);
check(count($files)===6&&!str_contains(implode(' ',array_keys($files)),'external'),'minimal workbook without external links or macros');foreach($files as $name=>$xml){$doc=new DOMDocument();check($doc->loadXML($xml,LIBXML_NONET),'well formed '.$name);}
$doc=new DOMDocument();$doc->loadXML($files['xl/worksheets/sheet1.xml'],LIBXML_NONET);$xp=new DOMXPath($doc);$xp->registerNamespace('s','http://schemas.openxmlformats.org/spreadsheetml/2006/main');$value=fn($cell)=>$xp->evaluate('string(//s:c[@r="'.$cell.'"]/s:is/s:t)');
check($value('A1')==='Name'&&$value('B1')==='Telefon'&&$value('C1')==='Anschrift'&&$xp->query('//s:row')->length===2,'selected columns and selected profile only');check($value('B2')==='001234567','leading zeros retained');check($value('C2')==="Teststraße 7\n01234 Musterort",'Unicode multiline address retained');check(str_starts_with($value('A2'),'=HYPERLINK')&&$xp->query('//s:f')->length===0&&$xp->evaluate('string(//s:c[@r="A2"]/@t)')==='inlineStr','formula-looking name remains literal text');check(!str_contains($files['xl/worksheets/sheet1.xml'],'Unselected')&&!str_contains($files['xl/worksheets/sheet1.xml'],'one@example.invalid'),'unselected rows and hidden columns absent');check($xp->evaluate('string(//s:pane/@topLeftCell)')==='A2'&&$xp->evaluate('string(//s:autoFilter/@ref)')==='A1:C2','readable frozen header and filter');
