denied(fn()=>(new Registry($db,'member'))->exportContacts([$one],['name'],'xlsx'),'member cannot export profiles');denied(fn()=>$r->exportContacts([$foreign],['name'],'xlsx'),'foreign club profile rejected');denied(fn()=>$r->exportContacts([],['name'],'xlsx'),'empty selection rejected');denied(fn()=>$r->exportContacts([$one,$one],['name'],'xlsx'),'duplicate selection rejected');denied(fn()=>$r->exportContacts([$one],['notes'],'xlsx'),'unapproved columns rejected');denied(fn()=>$r->exportContacts([$one],['name','name'],'xlsx'),'duplicate columns rejected');denied(fn()=>$r->exportContacts([$one],['name'],'php'),'unknown format rejected');
